	@Test
	void failedProducerOpeningRestoresExternalLeaseOwnership() throws Exception {
		NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(delegate.idSpace()).thenReturn(delegate);
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(delegate);
		NativeExecutionContext root = source.executionContext();
		root.initializeQueryBase(EmptyBindingSet.getInstance());
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("term", 0), null);
		layout.freeze(List.of("term"));
		RuntimeException expected = new IllegalStateException("controlled producer-open failure");
		NativeSubqueryPlan plan = new NativeSubqueryPlan(bindings -> {
			throw expected;
		}, new int[] { 0 }, new String[] { "term" }, new int[0], new String[0]);
		try {
			assertThatThrownBy(() -> plan.open(seededRow(source, layout))).isSameAs(expected);
			try (var external = root.retainLease()) {
				root.close();
				assertThat(root.isClosed())
						.as("failed producer scopes cannot turn later external readers into borrowers")
						.isFalse();
			}
			assertThat(root.isClosed()).isTrue();
		} finally {
			root.close();
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "true,false", "false,true", "true,true" })
	void unfinishedCachedProducerCannotRetainItsOwnAncestor(boolean shareTerms, boolean worker) throws Exception {
		NativeLmdbQuerySource delegate = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(delegate.idSpace()).thenReturn(delegate);
		when(delegate.idOf(any())).thenReturn(LmdbNativeAggregateCompiler.UNKNOWN);
		SyntheticValueSource source = SyntheticValueSource.forEvaluation(delegate);
		NativeExecutionContext root = source.executionContext();
		root.initializeQueryBase(EmptyBindingSet.getInstance());
		var ledger = root.memoryLedger();
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("term", 0), null);
		layout.freeze(List.of("term"));
		RowState row = seededRow(source, layout);
		AtomicReference<NestedProducer> producer = new AtomicReference<>();
		QueryEvaluationStep prepared = bindings -> {
			PlanValueCatalog catalog = shareTerms ? source.catalog : new PlanValueCatalog.Builder().build();
			SyntheticValueSource childSource = new SyntheticValueSource(delegate, catalog).forInvocation(bindings);
			NativeExecutionContext child = childSource.executionContext();
			assertThat(child).isNotSameAs(root);
			assertThat(child.memoryLedger()).isSameAs(ledger);
			NestedProducer nested = new NestedProducer(childSource, layout, worker);
			producer.set(nested);
			return new NativeContextClosingIteration(nested, child);
		};
		NativeSubqueryPlan plan = new NativeSubqueryPlan(prepared, new int[] { 0 }, new String[] { "term" },
				new int[0], new String[0]);
		RowCursor first = null;
		RowCursor second = null;
		try {
			first = plan.open(row);
			assertThat(first.next()).as("the outer replay admits its first complete row").isTrue();
			assertThat(source.lazyValue(row.id(0)).stringValue()).isEqualTo("member-0");
			assertThat(producer.get().innerRows).as("the inner batch is filled exactly, without an EOF poll")
					.isEqualTo(16);
			assertThat(producer.get().outerRows).as("the outer producer remains unfinished").isEqualTo(1);
			assertThat(producer.get().closes).hasValue(0);
			first.close();
			first = null;
			second = plan.open(row);
			assertThat(second.next()).isTrue();
			root.close();
			assertThat(root.isClosed()).as("an accepted external reader still retains every query owner").isFalse();
			assertThat(producer.get().closes).hasValue(0);
			assertThat(second.next()).as("an accepted reader can still advance the unfinished cached producer")
					.isTrue();
			assertThat(source.lazyValue(row.id(0)).stringValue()).isEqualTo("member-1");
			second.close();
			second = null;
			assertThat(root.isClosed())
					.as("the cached producer's internal exact-batch reader cannot prevent its own owner cleanup")
					.isTrue();
			assertThat(producer.get().closes).hasValue(1);
			assertThat(producer.get().source.executionContext().isClosed()).isTrue();
			assertThat(ledger.usedBytes()).isZero();
		} finally {
			if (first != null) {
				first.close();
			}
			if (second != null) {
				second.close();
			}
			// Keep a genuine pre-fix assertion failure recoverable without leaving the deliberate ownership cycle.
			if (producer.get() != null) {
				producer.get().close();
				producer.get().source.executionContext().close();
			}
			root.close();
		}
	}

	private static RowState seededRow(SyntheticValueSource source, NativeSlotLayout layout) {
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
		assertThat(row.boundMask()).isZero();
		assertThat(row.id(0)).isEqualTo(LmdbNativeAggregateCompiler.UNKNOWN);
		return row;
	}

	private static final class NestedProducer implements CloseableIteration<BindingSet> {
		private final SyntheticValueSource source;
		private final NativeSlotLayout layout;
		private final boolean worker;
		private final AtomicInteger closes = new AtomicInteger();
		private final List<BindingSet> batch = new ArrayList<>();
		private RowCursor inner;
		private int innerRows, outerRows;
		private boolean closed;

		private NestedProducer(SyntheticValueSource source, NativeSlotLayout layout, boolean worker) {
			this.source = source;
			this.layout = layout;
			this.worker = worker;
		}

		private void fillExactBatch() throws Exception {
			RowState row = seededRow(source, layout);
			List<BindingSet> members = new ArrayList<>();
			for (int index = 0; index < 16; index++) {
				MapBindingSet value = new MapBindingSet();
				value.addBinding("term", SimpleValueFactory.getInstance().createLiteral("member-" + index));
				members.add(value);
			}
			NativeSubqueryPlan innerPlan = new NativeSubqueryPlan(
					bindings -> new CloseableIteratorIteration<>(members.iterator()), new int[] { 0 },
					new String[] { "term" }, new int[0], new String[0]);
			try (RowCursor priming = innerPlan.open(row)) {
				for (int index = 0; index < 16; index++) {
					assertThat(priming.next()).as("the cached inner replay admits each source row").isTrue();
				}
				assertThat(priming.next()).as("the cached inner replay is complete").isFalse();
			}
			inner = innerPlan.open(row);
			for (int index = 0; index < 16; index++) {
				assertThat(inner.next()).as("all exact-batch input rows are admitted").isTrue();
				MapBindingSet value = new MapBindingSet();
				value.addBinding("term", source.lazyValue(row.id(0)));
				batch.add(value);
				innerRows++;
			}
		}

		@Override
		public boolean hasNext() {
			if (closed) {
				return false;
			}
			if (inner == null) {
				try {
					if (worker) {
						NativeExecutionContext.WorkerContext captured = NativeExecutionContext.captureWorkerContext();
						try (var executor = Executors.newSingleThreadExecutor()) {
							executor.submit(() -> {
								try (var activation = captured.activate()) {
									fillExactBatch();
								}
								return null;
							}).get(10, TimeUnit.SECONDS);
						}
					} else {
						fillExactBatch();
					}
				} catch (Exception failure) {
					throw new IllegalStateException(failure);
				}
			}
			return outerRows < 481;
		}

		@Override
		public BindingSet next() {
			assertThat(hasNext()).isTrue();
			return batch.get(outerRows++ % batch.size());
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			if (!closed) {
				closed = true;
				closes.incrementAndGet();
				if (inner != null) {
					inner.close();
				}
			}
		}
	}
